var SUGGQ=[{"k": "kol", "n": "Adam B. Yanke", "w": "Rush University Medical Center, Chicago (Stati Uniti)", "r": "Autore senior di due lavori distinti nella finestra recente (il TT-PCL/TT-TG di oggi in Arthroscopy e, il 7 settembre, il confronto sulla displasia trocleare) e già firma ricorrente su cartilagine e biomeccanica femoro-rotulea: corrispondenza tecnica diretta con la tua chirurgia del malallineamento rotuleo e dell'MPFL. Sostituisce la proposta invariata di Robert F. LaPrade (7 settembre), oggi comunque co-autore della scheda 8."}];
var EXTRA=[{dot:"gray",j:"International Journal of Surgery Case Reports",h:"Migrazione tardiva del bottone femorale dopo LCA all-epifisario in un adolescente",v:"Caso singolo: a quasi 5 anni da una ricostruzione all-epifisaria del LCA con semitendinoso in un paziente scheletricamente immaturo, il bottone femorale migra nell'articolazione nonostante l'innesto resti integro e ben incorporato; rimosso in artroscopia, recupero completo.",pmid:'42699891',doi:'10.1097/RC9.0000000000000814',temi:["lca adolescente", "tecnica risparmia-fisi", "complicanza"]},{dot:"gray",j:"Arthroscopy Techniques",h:"Una fissazione a doppio EndoButton per la frattura da avulsione tibiale del LCP",v:"Nota tecnica cinese: fissazione artroscopica con singola sutura e doppio EndoButton, passata sul versante laterale del LCA, per evitare di separare i due crociati durante la riduzione della frattura da avulsione tibiale del LCP; nessun dato clinico riportato.",pmid:'42701566',doi:'10.1002/atn2.70219',temi:["lcp", "frattura avulsione", "tecnica chirurgica"]},{dot:"gray",j:"The Archives of Bone and Joint Surgery",h:"L'acido tranexamico intra-articolare in artroscopia: dove siamo dopo cinque anni",v:"Editoriale di aggiornamento sull'uso intra-articolare dell'acido tranexamico nelle procedure artroscopiche di ginocchio, a cinque anni dalle prime evidenze: bilancio dei dati raccolti dal 2021 al 2025, nessun dato originale.",pmid:'42699815',doi:'10.22038/ABJS.2026.93762.4230',temi:["artroscopia", "emostasi", "farmacologia"]},{dot:"gray",j:"Chinese Journal of Reparative and Reconstructive Surgery",h:"Un consensus cinese sul percorso ERAS per la protesi di ginocchio ad alta congruenza",v:"Consensus Delphi di un panel multidisciplinare cinese sul percorso di recupero rapido (ERAS) per protesi di ginocchio con impianti ad alta congruenza personalizzati: raccomandazioni su valutazione preoperatoria, gestione intraoperatoria e riabilitazione, validità limitata al contesto sanitario cinese.",pmid:'42642184',doi:'10.7507/1002-1892.202606094',temi:["protesi totale", "eras", "consensus"]},{dot:"gray",j:"Journal of Robotic Surgery",h:"Un modello che lega gli osteofiti tibiali posteromediali al bilanciamento del gap nella protesi robotica",v:"Studio prospettico su 82 ginocchia: un nuovo indice («medial expected gap») lega la massa di osteofiti femorali e tibiali mediali alla correzione coronale ottenibile in protesi robot-assistita ad allineamento funzionale, con correzione media da 4,3° a 9,7° secondo la categoria di gap.",pmid:'42704404',doi:'10.1007/s11701-026-03883-8',temi:["protesi robotica", "allineamento", "osteofiti"]},{dot:"gray",j:"Arthroplasty (London)",h:"Impianto a pivot mediale o ultracongruente: il recupero del quadricipite non cambia",v:"RCT esplorativo su 30 pazienti: nessuna differenza nel recupero del quadricipite misurato con bioimpedenza fra protesi a pivot mediale e ultracongruente nel primo anno dopo protesi totale di ginocchio; campione piccolo, differenza clinicamente rilevante non esclusa.",pmid:'42702731',doi:'10.1186/s42836-026-00429-z',temi:["protesi totale", "quadricipite", "design impianto"]},{dot:"gray",j:"The Archives of Bone and Joint Surgery",h:"Che cosa mostra la risonanza del legamento antero-laterale prima della ricostruzione del LCA",v:"Studio su 83 candidati alla ricostruzione del LCA: una lesione RM del legamento antero-laterale è associata a versamento articolare e a un test del pivot-shift positivo, non a età, sesso o test del cassetto anteriore — a sfondo della tensione ancora aperta sul costrutto del rinforzo laterale.",pmid:'42699791',doi:'10.22038/ABJS.2025.87469.3956',temi:["let", "legamento antero-laterale", "imaging"]},{dot:"gray",j:"Musculoskeletal Surgery",h:"Le deformità torsionali dietro il dolore anteriore di ginocchio: una rassegna sistematica",v:"Revisione sistematica sulla «sindrome da malallineamento miserabile» (torsione femorale e tibiale associate): le osteotomie derotazionali restano il trattamento più diretto, ma livello, estensione e tempistica (a uno o due livelli, in uno o due tempi) restano dibattuti.",pmid:'42701950',doi:'10.1007/s12306-026-00983-4',temi:["instabilità rotulea", "torsione", "osteotomia"]},{dot:"gray",j:"Journal of Orthopaedic Case Reports",h:"L'assenza del robot non aumenta le cancellazioni il giorno dell'intervento in protesi di ginocchio",v:"Audit su due centri indiani, oltre 270 protesi programmate: solo due cancellazioni il giorno dell'intervento sono attribuite alla mancanza di un robot disponibile, entrambe in un solo centro — la fiducia costruita dal chirurgo pesa più della disponibilità della tecnologia.",pmid:'42598211',doi:'10.13107/jocr.2026.v16.i08.7888',temi:["protesi robotica", "organizzazione sanitaria", "aspettative del paziente"]},{dot:"gray",j:"The Knee",h:"Nella protesi robotica, alzare la linea articolare sul lato mediale peggiora l'esito a un anno",v:"Coorte coreana di 147 ginocchia con protesi robot-assistita ad allineamento funzionale: un'elevazione della linea articolare mediale oltre 2 mm rispetto al nativo si associa al punteggio Forgotten Joint peggiore a un anno, mentre una lieve depressione appare ben tollerata.",pmid:'42585985',doi:'10.1016/j.knee.2026.104594',temi:["protesi robotica", "allineamento", "esiti riferiti dal paziente"]},{dot:"gray",j:"Physical Therapy in Sport",h:"Se il trauma del LCA è multifattoriale, perché il test di rientro allo sport non lo è",v:"Un Masterclass a firma singola propone un framework di «allineamento dei determinanti» per la riabilitazione tardiva dopo LCA: forza, salto e questionari restano necessari ma coprono solo parte del sistema — percezione, cognizione e contesto sportivo pesano quanto la capacità fisica.",pmid:'42705007',doi:'10.1016/j.ptsp.2026.101988',temi:["criterio di rientro", "riabilitazione", "framework concettuale"]}];
var SCOPERTE=[{t:"Un esoscheletro cinese a doppio azionamento per aiutare gli anziani a camminare",v:"Un gruppo cinese descrive un esoscheletro di ginocchio leggero, con un solo motore e una frizione a servire entrambe le gambe, pensato per la locomozione quotidiana degli anziani: riconosce cammino in piano, rampe e scale con una precisione del 98,9% e riduce il costo metabolico misurato del 28,2% nei test con partecipanti anziani e giovani. È bioingegneria per la mobilità, non chirurgia — ma la stessa domanda (quanto sostegno serve al ginocchio, e quando) attraversa anche la tua pratica.",pmid:'42582671',doi:'10.34133/cbsystems.0576',temi:["bioingegneria", "esoscheletro", "mobilità anziani"]},{t:"Dal Giappone, una soletta robotica che corregge la caviglia per alleggerire il ginocchio artrosico",v:"Un dispositivo indossabile giapponese corregge dinamicamente l'allineamento della caviglia al contatto del tallone in pazienti con artrosi del comparto mediale, con l'obiettivo di ridurre il carico sul ginocchio senza intervenire sul ginocchio stesso. In sei pazienti, riduce la variabilità del carico orizzontale e l'oscillazione del centro di pressione durante il passo, senza cambiare il carico verticale — uno studio esplorativo di biomeccanica, non ancora una prova di efficacia clinica, ma un esempio di come la correzione a distanza di un'articolazione possa provare ad alleggerirne un'altra.",pmid:'42656284',doi:'10.3389/frobt.2026.1898805',temi:["bioingegneria", "robotica indossabile", "artrosi"]},{t:"Quanto pesa un disallineamento di due centimetri fra ginocchio umano ed esoscheletro",v:"Un gruppo cinese quantifica, con un modello uomo-esoscheletro e verifiche sperimentali, l'effetto di un disallineamento dell'asse di rotazione fra il ginocchio dell'esoscheletro e quello reale: a un disallineamento di 5 cm la coppia di estensione aumenta fino al 38,9% e quella di flessione fino al 211,2%. Gli autori ne ricavano un limite pratico di progettazione (entro 2 cm) per non compromettere l'efficacia dell'assistenza — ingegneria di precisione applicata a un problema di allineamento articolare, lo stesso linguaggio che usi ogni giorno in sala, applicato fuori dalla chirurgia.",pmid:'42655429',doi:'10.3390/s26165119',temi:["bioingegneria", "esoscheletro", "biomeccanica"]}];
